"use strict";
const titles={desk:"Clarity before execution.",research:"Study the workflow. Verify the claim.",evidence:"Evidence is the release criterion."};
function showView(view){document.querySelectorAll(".view").forEach(section=>section.hidden=section.id!==view);document.querySelectorAll("nav button").forEach(button=>{button.classList.toggle("selected",button.dataset.view===view);button.setAttribute("aria-pressed",String(button.dataset.view===view));});document.getElementById("page-title").textContent=titles[view];}
document.querySelectorAll("[data-view]").forEach(button=>button.addEventListener("click",()=>showView(button.dataset.view)));
document.getElementById("inspect").addEventListener("click",()=>showView("evidence"));
const points=Array.from({length:60},(_,i)=>[28+i*12.5,175-Math.sin(i*.23)*32-Math.cos(i*.71)*10-i*.75]);
function plot(){const count=Number(document.getElementById("replay").value);document.getElementById("bar-number").textContent=count;const fixture=document.getElementById("scenario").value==="replay";let grid="";for(let y=35;y<280;y+=55){grid+=`<path d="M20 ${y}H790" stroke="#252c35" stroke-dasharray="3 5"/><text x="800" y="${y+3}" fill="#677586" font-size="9">${(102-(y-35)/110).toFixed(1)}</text>`;}for(let x=35;x<790;x+=150){grid+=`<text x="${x}" y="295" fill="#677586" font-size="9">bar ${Math.round((x-28)/12.5)+1}</text>`;}if(fixture){const series=points.slice(0,count);const d=series.map(([x,y],i)=>`${i?"L":"M"}${x} ${y}`).join(" ");const end=series.at(-1);grid+=`<path d="${d} L${end[0]} 275 L28 275Z" fill="url(#area)"/>`;for(const offset of [-38,38]){const b=series.map(([x],i)=>`${i?"L":"M"}${x} ${155-i*.6+offset}`).join(" ");grid+=`<path d="${b}" stroke="#526075" fill="none" stroke-dasharray="4 5"/>`;}grid+=`<path d="${d}" stroke="#cbb47c" stroke-width="2" fill="none"/><circle cx="${end[0]}" cy="${end[1]}" r="4" fill="#e4d1a2"/><path d="M${end[0]} 20V275" stroke="#6f6653" stroke-dasharray="3 5"/>`;}else{grid+='<text x="250" y="155" fill="#a4acb7" font-size="16">No usable price data</text>';}
document.getElementById("plot").innerHTML=grid;}
document.getElementById("replay").addEventListener("input",plot);
document.getElementById("scenario").addEventListener("change",()=>{const value=document.getElementById("scenario").value;const state={replay:["Synthetic replay","Illustrative price index, not market prices","Synthetic replay fixture. No live feed, broker connection, or order controls."],missing:["No data","No source sample received","No source data. Unknown exposure and feed health must remain unknown."],stale:["Stale data","Simulated stale-feed scenario","Stale-feed scenario. Previous observations cannot authorize a new order."]}[value];document.getElementById("feed-state").textContent=state[0];document.getElementById("feed-detail").textContent=state[1];document.getElementById("notice-text").textContent=state[2];document.getElementById("replay").disabled=value!=="replay";plot();});
showView("desk");plot();
